using System.Diagnostics;
using System.Globalization;
using NAudio.Wave;
using static DiscordDeck.Lang;
namespace DiscordDeck;
static class YouTubeImport {
 public static string Tool(string name){var local=Path.Combine(AppContext.BaseDirectory,"tools",name+".exe");if(File.Exists(local))return local;throw new IOException(T("Import-Werkzeug fehlt: ","Import tool missing: ")+name);}
 static async Task Run(string tool,IEnumerable<string> args,CancellationToken token){var info=new ProcessStartInfo(Tool(tool)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true};foreach(var a in args)info.ArgumentList.Add(a);using var p=Process.Start(info)??throw new IOException(T("Werkzeug startet nicht.","Tool does not start."));var stdout=p.StandardOutput.ReadToEndAsync();var stderr=p.StandardError.ReadToEndAsync();try{await p.WaitForExitAsync(token);}catch{try{p.Kill(true);}catch{}throw;}await stdout;var error=await stderr;if(p.ExitCode!=0)throw new IOException(Explain(error));}
 static string Explain(string error){var lines=error.Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);var err=lines.LastOrDefault(l=>l.StartsWith("ERROR:"))??lines.LastOrDefault()??T("Unbekannter Fehler","Unknown error");if(err.Contains("not a bot",StringComparison.OrdinalIgnoreCase)||err.Contains("Sign in to confirm",StringComparison.OrdinalIgnoreCase))return T("YouTube blockiert den Download (Bot-Prüfung). Meist liegt das an einem VPN wie Cloudflare WARP oder NordVPN: VPN kurz ausschalten oder YouTube davon ausnehmen und erneut laden.","YouTube is blocking the download (bot check). This is usually caused by a VPN such as Cloudflare WARP or NordVPN: turn the VPN off briefly or exclude YouTube, then load again.");if(err.Contains("Video unavailable",StringComparison.OrdinalIgnoreCase)||err.Contains("Private video",StringComparison.OrdinalIgnoreCase))return T("Video nicht verfügbar (privat, gelöscht oder gesperrt).","Video unavailable (private, deleted or blocked).");if(err.Contains("age",StringComparison.OrdinalIgnoreCase)&&err.Contains("confirm",StringComparison.OrdinalIgnoreCase))return T("Video ist altersbeschränkt und kann ohne Anmeldung nicht geladen werden.","Video is age-restricted and cannot be loaded without signing in.");return err.Length>300?err[..300]:err;}
 static bool Allowed(string host){host=host.ToLowerInvariant();foreach(var d in new[]{"youtube.com","youtu.be","tiktok.com"})if(host==d||host.EndsWith("."+d))return true;return false;}
 public static async Task<string> Download(string url,string folder,CancellationToken token){if(!Uri.TryCreate(url,UriKind.Absolute,out var uri)||uri.Scheme!="https"||!Allowed(uri.Host)||!string.IsNullOrEmpty(uri.UserInfo)||!uri.IsDefaultPort)throw new ArgumentException(T("Bitte einen HTTPS-Link von YouTube, YouTube Shorts oder TikTok eingeben.","Please enter an HTTPS link from YouTube, YouTube Shorts or TikTok."));Directory.CreateDirectory(folder);for(int attempt=1;;attempt++){try{await Run("yt-dlp",new[]{"--ignore-config","--js-runtimes","deno:"+Tool("deno"),"--no-playlist","--no-progress","--socket-timeout","20","--retries","5","--fragment-retries","5","--max-filesize","200M","--match-filter","!is_live & duration <= 7200","--ffmpeg-location",Path.GetDirectoryName(Tool("ffmpeg"))!,"-f","bestaudio/best","-x","--audio-format","mp3","--windows-filenames","-o",Path.Combine(folder,"%(title).120B.%(ext)s"),"--",url},token);break;}catch(IOException e)when(attempt<3&&!token.IsCancellationRequested&&(e.Message.Contains("403")||e.Message.Contains("timed out",StringComparison.OrdinalIgnoreCase)||e.Message.Contains("Connection",StringComparison.OrdinalIgnoreCase))){foreach(var f in Directory.GetFiles(folder))try{File.Delete(f);}catch{}await Task.Delay(1500*attempt,token);}}return Directory.GetFiles(folder,"*.mp3").SingleOrDefault()??throw new IOException(T("Keine Audiodatei erhalten (Video eventuell nicht verfügbar).","No audio file received (the video may be unavailable)."));}
 public static async Task Trim(string source,string destination,double start,double end,CancellationToken token){using(var probe=new AudioFileReader(source)){if(!double.IsFinite(start)||!double.IsFinite(end)||start<0||end<=start||end>probe.TotalTime.TotalSeconds+.05)throw new ArgumentException(T("Ende muss nach Start und innerhalb des Sounds liegen.","End must be after start and inside the sound."));}await Run("ffmpeg",new[]{"-nostdin","-v","error","-y","-ss",start.ToString(CultureInfo.InvariantCulture),"-i",source,"-t",(end-start).ToString(CultureInfo.InvariantCulture),"-vn","-c:a","libmp3lame","-q:a","2",destination},token);using var check=new AudioFileReader(destination);if(check.TotalTime.TotalSeconds<=0)throw new IOException(T("Leerer Ausschnitt.","Empty clip."));}
 public static void Show(Form owner,Settings settings,Action changed){using var form=new Form{Text=T("YouTube / TikTok-Audio importieren und schneiden","Import and trim YouTube / TikTok audio"),Size=new Size(670,460),StartPosition=FormStartPosition.CenterParent};var root=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(16)};form.Controls.Add(root);var url=new TextBox{Width=600,PlaceholderText=T("YouTube-, Shorts- oder TikTok-Link einfügen","Paste a YouTube, Shorts or TikTok link")};root.Controls.Add(url);var load=new Button{Text=T("Audio herunterladen","Download audio"),AutoSize=true};root.Controls.Add(load);var status=new Label{Text=T("Link einfügen und laden.","Paste a link and load it."),Width=600,Height=70};root.Controls.Add(status);root.Controls.Add(new Label{Text=T("Start / Ende in Sekunden","Start / end in seconds"),AutoSize=true});var times=new FlowLayoutPanel{Width=600,Height=40};var from=new NumericUpDown{Maximum=7200,DecimalPlaces=2,Width=150};var to=new NumericUpDown{Maximum=7200,DecimalPlaces=2,Width=150};times.Controls.Add(from);times.Controls.Add(to);root.Controls.Add(times);var preview=new Button{Text=T("Ausschnitt vorhören","Preview clip"),AutoSize=true,Enabled=false};root.Controls.Add(preview);var slots=new ComboBox{Width=600,DropDownStyle=ComboBoxStyle.DropDownList};for(int i=0;i<settings.Slots.Count;i++)slots.Items.Add($"{i+1}: {settings.Slots[i].Name}");slots.SelectedIndex=0;root.Controls.Add(slots);var save=new Button{Text=T("Ausschnitt auf diesen Knopf legen","Put this clip on the button"),AutoSize=true,Enabled=false};root.Controls.Add(save);using var cancel=new CancellationTokenSource();var folder=Path.Combine(Path.GetTempPath(),"DiscordDeck-"+Guid.NewGuid().ToString("N"));string? source=null;WaveOutEvent? player=null;AudioFileReader? reader=null;bool busy=false;
 void Stop(){player?.Stop();player?.Dispose();reader?.Dispose();player=null;reader=null;}
 void Busy(bool value){busy=value;load.Enabled=!value;preview.Enabled=save.Enabled=!value&&source!=null;}
 load.Click+=async(_,_)=>{Busy(true);Stop();status.Text=T("Lade Audio …","Loading audio …");try{source=await Download(url.Text.Trim(),Path.Combine(folder,Guid.NewGuid().ToString("N")),cancel.Token);using var probe=new AudioFileReader(source);from.Value=0;to.Value=(decimal)Math.Min(7200,probe.TotalTime.TotalSeconds);status.Text=Path.GetFileNameWithoutExtension(source);}catch(Exception e){status.Text=e is OperationCanceledException?T("Abgebrochen","Cancelled"):e.Message;}finally{Busy(false);}};
 preview.Click+=async(_,_)=>{Busy(true);Stop();try{var file=Path.Combine(folder,"preview.mp3");await Trim(source!,file,(double)from.Value,(double)to.Value,cancel.Token);reader=new AudioFileReader(file);player=new WaveOutEvent();player.Init(reader);player.Play();}catch(Exception e){status.Text=e.Message;}finally{Busy(false);}};
 save.Click+=async(_,_)=>{Busy(true);Stop();string? target=null;try{var index=slots.SelectedIndex;var title=Path.GetFileNameWithoutExtension(source!);var dest=Path.Combine(Settings.Folder,"Sounds","YouTube",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dest);target=Path.Combine(dest,title+".mp3");await Trim(source!,target,(double)from.Value,(double)to.Value,cancel.Token);var slot=settings.Slots[index];slot.File=target;slot.TrimStart=slot.TrimEnd=0;slot.Name=title;slot.SourceUrl=url.Text.Trim();settings.Save();changed();status.Text=T($"Gespeichert auf Knopf {index+1}: {title}",$"Saved to button {index+1}: {title}");}catch(Exception e){if(target!=null&&File.Exists(target))File.Delete(target);status.Text=e.Message;}finally{Busy(false);}};
 form.FormClosing+=(_,e)=>{if(busy){cancel.Cancel();e.Cancel=true;status.Text=T("Vorgang wird abgebrochen. Danach Fenster schließen.","Cancelling. Close the window afterwards.");}};DeckTheme.Apply(form);form.ShowDialog(owner);Stop();try{if(Directory.Exists(folder))Directory.Delete(folder,true);}catch{}
 }
}
